package xlang

import (
	"fmt"

	"google.golang.org/protobuf/proto"
	"google.golang.org/protobuf/reflect/protoreflect"
	"google.golang.org/protobuf/reflect/protoregistry"
)

// vtMessage is the fast-path method set generated by protoc-gen-go-vtproto.
// It is asserted structurally so this package does not import vtprotobuf
// itself; only the generated code links it.
type vtMessage interface {
	UnmarshalVT([]byte) error
	MarshalToVT([]byte) (int, error)
	SizeVT() int
}

// vtSession is a Session over generated types via vtprotobuf's
// UnmarshalVT/MarshalToVT fast paths. vtprotobuf has no deterministic
// marshaller, so the deterministic form used only by verification step 2/3
// comes from the standard runtime over the same generated type.
type vtSession struct {
	mt         protoreflect.MessageType
	marshalDet proto.MarshalOptions
}

// NewVTSession resolves message in the global registry and requires the
// vtprotobuf fast-path methods; without them the cell is Unsupported.
// excluded maps proto paths skipped by codegen.sh to the reason, so those
// cells report precisely why instead of a generic message.
func NewVTSession(message string, excluded map[string]string) (Session, error) {
	mt, err := protoregistry.GlobalTypes.FindMessageByName(protoreflect.FullName(message))
	if err != nil {
		return nil, fmt.Errorf("message %s not registered in this binary: %w", message, err)
	}
	if _, ok := mt.New().Interface().(vtMessage); !ok {
		reason := fmt.Sprintf("message %s has no vtprotobuf fast paths", message)
		if r, ok := excluded[mt.Descriptor().ParentFile().Path()]; ok {
			reason = fmt.Sprintf("message %s excluded from vtproto codegen: %s", message, r)
		}
		return nil, Unsupported{Reason: reason}
	}
	return &vtSession{mt: mt, marshalDet: proto.MarshalOptions{Deterministic: true}}, nil
}

func (s *vtSession) NewMessage() proto.Message { return s.mt.New().Interface() }

func (s *vtSession) Parse(m proto.Message, b []byte) error {
	vm, ok := m.(vtMessage)
	if !ok {
		return Unsupported{Reason: "message lost vtprotobuf fast paths"}
	}
	return vm.UnmarshalVT(b)
}

func (s *vtSession) MarshalAppend(m proto.Message, buf []byte) ([]byte, error) {
	vm, ok := m.(vtMessage)
	if !ok {
		return nil, Unsupported{Reason: "message lost vtprotobuf fast paths"}
	}
	size := vm.SizeVT()
	if cap(buf) < size {
		buf = make([]byte, 0, size)
	}
	out := buf[:size]
	n, err := vm.MarshalToVT(out)
	if err != nil {
		return nil, err
	}
	return out[:n], nil
}

func (s *vtSession) MarshalDeterministic(m proto.Message) ([]byte, error) {
	return s.marshalDet.Marshal(m)
}
